import AxonContext from '#class/axonContext';

import ClaimService from '#serv/claims';
import CommunicatieService from '#serv/communicaties';
import DocumentenService from '#serv/documenten';
import HandboekingenService from '#serv/handboekingen';
import OpgavenService from '#serv/opgaven';
import PolissenService from '#serv/polissen';
import PolisversieService from '#serv/polisversies';

function lazy<T>(create: () => T) {
    let instance: T | undefined;
    return () => instance ??= create();
}

/**
 * ## AxonController
 *
 * Een concrete sessie-wrapper rond `AxonContext` die handige, luie
 * toegang biedt tot de verschillende Axon-services (communicatie,
 * documenten, opgaven en handboekingen).
 *
 * Gebruik `AxonController.create()` om een ingelogde instantie te
 * verkrijgen die klaar is voor gebruik met de service-getters.
 * 
 * @extends AxonContext
 */
export default class AxonController extends AxonContext {
    /**
     * Maak een nieuwe, ingelogde `AxonController` aan.
     * @param useTest - Bepaalt of pre-Axon gebruikt moet worden, i.p.v. Axon
     * @returns Een ingelogde `AxonController` instantie.
     */
    static async create(useTest: boolean = true, connections: number = 2) {
        if (!useTest) console.debug("Let op: dit is niet in de testomgeving.");
        const session = new AxonController(useTest, connections);
        await session.login();
        return session;
    }

    get claims() { return this.#claims(); }
    get communicaties() { return this.#communicatie(); }
    get documenten() { return this.#documenten(); }
    get handboekingen() { return this.#handboekingen(); }
    get opgaven() { return this.#opgaven(); }
    get polissen() { return this.#polissen(); }
    get polisversies() { return this.#polisversies(); }

    #claims = lazy(() => new ClaimService(this));
    #communicatie = lazy(() => new CommunicatieService(this));
    #documenten = lazy(() => new DocumentenService(this));
    #handboekingen = lazy(() => new HandboekingenService(this));
    #opgaven = lazy(() => new OpgavenService(this));
    #polissen = lazy(() => new PolissenService(this));
    #polisversies = lazy(() => new PolisversieService(this));
}
